import json
for tf in ["minute","5minute"]:
    R=json.load(open(f"studies/operating_point_sizing/results_{tf}.json"))
    print("=====",tf, R["meta"])
    fam=R["family"]
    print({k:v for k,v in fam.items() if k!="best_row"})
    br=fam["best_row"]
    print("BEST", {k:v for k,v in br.items() if k not in ("go_no_go",)})
    for k,v in br["go_no_go"]["checks"].items(): print("   ",k,v if len(str(v))<200 else str(v)[:200])
    for k,M in R["models"].items():
        print("--",k, M["role"][:40], "AUC",M["p_summary"]["auc_oof"], "cost", M["cost_sensitivity"], "alpha_rule", M["conformal_alpha_rule"], "pareto", M["pareto_argmax_coverage_by_w"])
        for c in M["conformal"]:
            print("   conf",c["alpha"],"cov",c["winner_coverage"],c["winner_coverage_weighted"],"fold<nom/<cv+",c["folds_below_nominal"],c["folds_below_cv_plus"],"kept",c["ledger"]["kept_share"],"diff",c["ledger"]["diff"],"ctrl",c["ledger"]["control_pct"],"perm",c["ledger"]["perm_p"],"slip8",c["ledger"]["kept_mean_slip8"],"top1",c["ledger"]["diff_top1_removed"],c["ledger"]["id"])
        for x in M["crc"]["chosen"]:
            if "ledger" in x: print("   crc",x["alpha"],x["coverage_lambda"],"cert",x["certificate"],"pre",x["realised_risk_before_block"],"ratio",round(x["realised_risk_before_block"]/x["certificate"],2),"allIS",x["realised_risk_all_is"],"diff",x["ledger"]["diff"],"ctrl",x["ledger"]["control_pct"],x["ledger"]["id"])
            else: print("   crc",x)
EOF

